-- Storage foundations only. P1 exposes no task execution API.
CREATE TABLE sessions (session_id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('main','worker')), worker_id TEXT REFERENCES workers(worker_id), workspace_id TEXT, workspace_version INTEGER, repo_id TEXT, path TEXT, CHECK((kind='main' AND worker_id IS NULL AND workspace_id IS NULL) OR (kind='worker' AND worker_id IS NOT NULL AND workspace_id IS NOT NULL)));
CREATE TABLE jobs (job_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), client_request_id TEXT NOT NULL, request_hash TEXT NOT NULL, worker_id TEXT REFERENCES workers(worker_id), queue_seq INTEGER UNIQUE, state TEXT NOT NULL CHECK(state IN ('queued','running','waiting_worker','waiting_children','cancel_requested','succeeded','failed','cancelled','needs_attention')), cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancel_requested IN (0,1)), parent_job_id TEXT REFERENCES jobs(job_id), delegation_id TEXT, created_at INTEGER NOT NULL, started_at INTEGER, UNIQUE(session_id,client_request_id), UNIQUE(parent_job_id,delegation_id));
CREATE TABLE messages (message_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), job_id TEXT NOT NULL REFERENCES jobs(job_id), seq INTEGER NOT NULL, content_json TEXT NOT NULL, UNIQUE(session_id,seq));
CREATE TABLE tool_calls (call_id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(job_id), call_seq INTEGER NOT NULL, request_hash TEXT NOT NULL, request_json TEXT NOT NULL, result_json TEXT, state TEXT NOT NULL CHECK(state IN ('pending','accepted','running','finished','unknown')), UNIQUE(job_id,call_seq));
CREATE TABLE runtime_checkpoints (job_id TEXT PRIMARY KEY REFERENCES jobs(job_id), revision INTEGER NOT NULL, content_json TEXT NOT NULL);
CREATE TABLE events (event_id INTEGER PRIMARY KEY AUTOINCREMENT, created_at INTEGER NOT NULL, content_json TEXT NOT NULL);
CREATE TABLE job_dependencies (job_id TEXT NOT NULL REFERENCES jobs(job_id), depends_on_job_id TEXT NOT NULL REFERENCES jobs(job_id), PRIMARY KEY(job_id,depends_on_job_id), CHECK(job_id<>depends_on_job_id));
CREATE TABLE attention_actions (action_id TEXT PRIMARY KEY, worker_id TEXT NOT NULL REFERENCES workers(worker_id), job_id TEXT REFERENCES jobs(job_id), action TEXT NOT NULL, evidence TEXT NOT NULL, created_at INTEGER NOT NULL);
